5	export class ExceptionHelper {
6	  static badRequest(errorCode: ErrorCodeEnum, message: string): never {
7	    return ExceptionHelper.raise(HttpStatus.BAD_REQUEST, errorCode, message);
8	  }
9	
10	  static notFound(errorCode: ErrorCodeEnum, message: string): never {
11	    return ExceptionHelper.raise(HttpStatus.NOT_FOUND, errorCode, message);
12	  }
13	
14	  static conflict(errorCode: ErrorCodeEnum, message: string): never {
15	    return ExceptionHelper.raise(HttpStatus.CONFLICT, errorCode, message);
16	  }
17	
18	  static unprocessable(errorCode: ErrorCodeEnum, message: string): never {
19	    return ExceptionHelper.raise(HttpStatus.UNPROCESSABLE_ENTITY, errorCode, message);
20	  }
21	
22	  static serviceUnavailable(errorCode: ErrorCodeEnum, message: string): never {
23	    return ExceptionHelper.raise(HttpStatus.SERVICE_UNAVAILABLE, errorCode, message);
24	  }
25	
26	  private static raise(statusCode: HttpStatus, errorCode: ErrorCodeEnum, message: string): never {
27	    const error: ErrorResponseDto = { statusCode, errorCode, message };
28	    throw new RpcException(error);
29	  }
30	}
