1	import { ArgumentsHost, BadRequestException, HttpServer, Logger, NotFoundException } from '@nestjs/common';
2	import { RpcException } from '@nestjs/microservices';
3	import { ErrorCodeEnum } from '@roombook/contract';
4	import { RpcExceptionFilter } from './rpc-exception.filter';
5	
6	describe('RpcExceptionFilter', () => {
7	  const response = { kind: 'response' };
8	  const host = {
9	    getArgByIndex: (): unknown => response,
10	    switchToHttp: () => ({ getResponse: (): unknown => response }),
11	  } as unknown as ArgumentsHost;
12	  let reply: jest.Mock;
13	  let filter: RpcExceptionFilter;
14	
15	  beforeEach(() => {
16	    reply = jest.fn();
17	    const adapter = { reply, isHeadersSent: () => false, end: jest.fn() } as unknown as HttpServer;
18	    filter = new RpcExceptionFilter(adapter);
19	    jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
20	  });
21	
22	  afterEach(() => jest.restoreAllMocks());
23	
24	  it('answers the status and body of a domain RpcException', () => {
25	    const body = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' };
26	
27	    filter.catch(new RpcException(body), host);
28	
29	    expect(reply).toHaveBeenCalledWith(response, body, 404);
30	  });
31	
32	  it('answers a domain error relayed from a service as a plain object', () => {
33	    const body = { statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE, message: 'down' };
34	
35	    filter.catch(body, host);
36	
37	    expect(reply).toHaveBeenCalledWith(response, body, 503);
38	  });
39	
40	  it('answers a validation failure with 400 and the validation error code', () => {
41	    filter.catch(new BadRequestException(['page must not be less than 1', 'limit must be an integer']), host);
42	
43	    expect(reply).toHaveBeenCalledWith(
44	      response,
45	      {
46	        statusCode: 400,
47	        errorCode: ErrorCodeEnum.VALIDATION,
48	        message: 'page must not be less than 1, limit must be an integer',
49	      },
50	      400,
51	    );
52	  });
53	
54	  it('keeps the status of any other HTTP exception', () => {
55	    filter.catch(new NotFoundException('Cannot GET /api/unknown'), host);
56	
57	    expect(reply).toHaveBeenCalledWith(response, expect.objectContaining({ statusCode: 404 }), 404);
58	  });
59	
60	  it('answers 500 for a plain Error', () => {
61	    filter.catch(new Error('boom'), host);
62	
63	    expect(reply).toHaveBeenCalledWith(response, expect.objectContaining({ statusCode: 500 }), 500);
64	  });
65	
66	  it('answers 500 for an unknown error relayed from a service', () => {
67	    filter.catch({ status: 'error', message: 'Internal server error' }, host);
68	
69	    expect(reply).toHaveBeenCalledWith(response, expect.objectContaining({ statusCode: 500 }), 500);
70	  });
71	});
