1	import { RpcException } from '@nestjs/microservices';
2	import { ErrorCodeEnum } from '@roombook/contract';
3	import { ExceptionHelper } from './exception.helper';
4	
5	const thrownBy = (raise: () => never): RpcException => {
6	  try {
7	    raise();
8	  } catch (error) {
9	    if (error instanceof RpcException) {
10	      return error;
11	    }
12	    throw error;
13	  }
14	  throw new Error('nothing was thrown');
15	};
16	
17	describe('ExceptionHelper', () => {
18	  it('throws a not found RpcException with the contract error body', () => {
19	    const exception = thrownBy(() => ExceptionHelper.notFound(ErrorCodeEnum.ROOM_NOT_FOUND, 'x'));
20	
21	    expect(exception.getError()).toEqual({ statusCode: 404, errorCode: 'NOT_FOUND.ROOM', message: 'x' });
22	  });
23	
24	  it.each([
25	    ['badRequest', ErrorCodeEnum.VALIDATION, 400],
26	    ['conflict', ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS, 409],
27	    ['unprocessable', ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED, 422],
28	    ['serviceUnavailable', ErrorCodeEnum.SERVICE_UNAVAILABLE, 503],
29	  ] as const)('%s answers %s with status %i', (method, errorCode, statusCode) => {
30	    const exception = thrownBy(() => ExceptionHelper[method](errorCode, 'reason'));
31	
32	    expect(exception.getError()).toEqual({ statusCode, errorCode, message: 'reason' });
33	  });
34	});
