7	export const NATS_REQUEST_TIMEOUT_MS = 5000;
8	
9	const isUnanswered = (error: unknown): boolean =>
10	  error instanceof TimeoutError || error instanceof EmptyResponseException;
11	
12	export class NatsRequestUtil {
13	  static send<TResult, TInput>(client: ClientProxy, pattern: string, data: TInput): Promise<TResult> {
14	    return lastValueFrom(
15	      client.send<TResult, TInput>(pattern, data).pipe(
16	        timeout(NATS_REQUEST_TIMEOUT_MS),
17	        catchError((error: unknown) =>
18	          isUnanswered(error)
19	            ? ExceptionHelper.serviceUnavailable(ErrorCodeEnum.SERVICE_UNAVAILABLE, `No service answered ${pattern}`)
20	            : throwError(() => error),
21	        ),
22	      ),
23	    );
24	  }
25	}
