4	import { NEVER, Observable, of, throwError } from 'rxjs';
5	import { NatsRequestUtil } from './nats-request.util';
6	
7	const clientReturning = (result: Observable<unknown>): { client: ClientProxy; send: jest.Mock } => {
8	  const send = jest.fn().mockReturnValue(result);
9	  return { client: { send } as unknown as ClientProxy, send };
10	};
11	
12	const errorOf = async (promise: Promise<unknown>): Promise<unknown> =>
13	  promise.then(
14	    () => undefined,
15	    (error) => error,
16	  );
17	
18	describe('NatsRequestUtil.send', () => {
19	  afterEach(() => jest.useRealTimers());
20	
21	  it('resolves with the reply of the pattern', async () => {
22	    const { client, send } = clientReturning(of({ status: 'ok' }));
23	
24	    await expect(NatsRequestUtil.send(client, 'health:room', {})).resolves.toEqual({ status: 'ok' });
25	    expect(send).toHaveBeenCalledWith('health:room', {});
26	  });
27	
28	  it('rejects with a 503 once the reply takes longer than 5 seconds, without retrying', async () => {
29	    jest.useFakeTimers();
30	    const { client, send } = clientReturning(NEVER);
