import { ConfirmationStatusEnum } from '@roombook/contract';
import type { BookingDto, CreateBookingDto, PagedBookingsDto } from '@roombook/contract';
import { apiClient } from './api-client';
import { createBooking, deleteBooking, listBookings, updateBooking } from './booking.service';

jest.mock('./api-client', () => ({
  apiClient: { get: jest.fn(), post: jest.fn(), patch: jest.fn(), delete: jest.fn() },
}));

const mockedGet = apiClient.get as jest.Mock;
const mockedPost = apiClient.post as jest.Mock;
const mockedPatch = apiClient.patch as jest.Mock;
const mockedDelete = apiClient.delete as jest.Mock;

const ROOM_ID = 'a1b2c3d4-0000-4000-8000-000000000001';
const BOOKING_ID = 'b1b2c3d4-0000-4000-8000-000000000001';

const booking: BookingDto = {
  id: BOOKING_ID,
  roomId: ROOM_ID,
  title: 'Planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

describe('booking.service', () => {
  beforeEach(() => jest.resetAllMocks());

  it('listBookings requests GET /bookings with page and limit only when no room is set', async () => {
    const body: PagedBookingsDto = { items: [booking], total: 1, page: 2, limit: 10 };
    mockedGet.mockResolvedValue({ data: body });

    const result = await listBookings({ page: 2, limit: 10 });

    expect(mockedGet).toHaveBeenCalledTimes(1);
    expect(mockedGet.mock.calls[0]).toStrictEqual(['/bookings', { params: { page: 2, limit: 10 } }]);
    expect(result).toEqual(body);
  });

  it('listBookings adds roomId when it is set', async () => {
    mockedGet.mockResolvedValue({ data: { items: [], total: 0, page: 1, limit: 10 } });

    await listBookings({ page: 1, limit: 10, roomId: ROOM_ID });

    expect(mockedGet.mock.calls[0]).toStrictEqual(['/bookings', { params: { page: 1, limit: 10, roomId: ROOM_ID } }]);
  });

  it('createBooking posts the body to /bookings with the Idempotency-Key header', async () => {
    const body: CreateBookingDto = {
      roomId: ROOM_ID,
      title: 'Planning',
      organizerEmail: 'ann@example.com',
      startsAt: '2030-01-07T09:00:00.000Z',
      endsAt: '2030-01-07T10:00:00.000Z',
    };
    const key = 'c1b2c3d4-0000-4000-8000-000000000001';
    mockedPost.mockResolvedValue({ data: booking });

    const result = await createBooking(body, key);

    expect(mockedPost).toHaveBeenCalledWith('/bookings', body, { headers: { 'Idempotency-Key': key } });
    expect(result).toEqual(booking);
  });

  it('updateBooking patches /bookings/:id with the changes', async () => {
    const changes = { title: 'Retro' };
    mockedPatch.mockResolvedValue({ data: { ...booking, title: 'Retro' } });

    const result = await updateBooking(BOOKING_ID, changes);

    expect(mockedPatch).toHaveBeenCalledWith(`/bookings/${BOOKING_ID}`, changes);
    expect(result.title).toBe('Retro');
  });

  it('deleteBooking deletes /bookings/:id and resolves with nothing', async () => {
    mockedDelete.mockResolvedValue({ data: '' });

    await expect(deleteBooking(BOOKING_ID)).resolves.toBeUndefined();

    expect(mockedDelete).toHaveBeenCalledWith(`/bookings/${BOOKING_ID}`);
  });

  it('propagates a rejected request', async () => {
    const failure = new Error('boom');
    mockedGet.mockRejectedValue(failure);

    await expect(listBookings({ page: 1, limit: 10 })).rejects.toBe(failure);
  });
});

import { isErrorResponse } from './error-response.guard';

describe('isErrorResponse', () => {
  it('accepts an object with a numeric status, a string error code and a string message', () => {
    expect(isErrorResponse({ statusCode: 404, errorCode: 'NOT_FOUND.ROOM', message: 'x' })).toBe(true);
  });

  it.each([
    ['null', null],
    ['a string', 'NOT_FOUND.ROOM'],
    ['a missing statusCode', { errorCode: 'NOT_FOUND.ROOM', message: 'x' }],
    ['a missing errorCode', { statusCode: 404, message: 'x' }],
    ['a missing message', { statusCode: 404, errorCode: 'NOT_FOUND.ROOM' }],
    ['a string statusCode', { statusCode: '404', errorCode: 'NOT_FOUND.ROOM', message: 'x' }],
    ['a numeric errorCode', { statusCode: 404, errorCode: 404, message: 'x' }],
    ['a non-string message', { statusCode: 404, errorCode: 'NOT_FOUND.ROOM', message: ['x'] }],
  ])('rejects %s', (_case, value) => {
    expect(isErrorResponse(value)).toBe(false);
  });
});

import { formatDateTime, toLocalInputValue, toUtcIso } from './booking-date.util';

describe('booking-date.util', () => {
  it('toUtcIso turns a datetime-local value into the UTC ISO string of the same local instant', () => {
    expect(toUtcIso('2030-01-07T09:05')).toBe(new Date(2030, 0, 7, 9, 5).toISOString());
  });

  it('toLocalInputValue turns an ISO string into YYYY-MM-DDTHH:mm local time', () => {
    const iso = new Date(2030, 10, 3, 4, 5).toISOString();

    expect(toLocalInputValue(iso)).toBe('2030-11-03T04:05');
  });

  it('toLocalInputValue round-trips with toUtcIso', () => {
    expect(toLocalInputValue(toUtcIso('2030-12-31T23:59'))).toBe('2030-12-31T23:59');
    expect(toUtcIso(toLocalInputValue('2030-06-15T12:30:00.000Z'))).toBe('2030-06-15T12:30:00.000Z');
  });

  it('formatDateTime returns the locale string of the instant', () => {
    const iso = '2030-01-07T09:00:00.000Z';

    expect(formatDateTime(iso)).toBe(new Date(iso).toLocaleString());
  });
});

import { BookingEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum } from '@roombook/contract';
import { toBookingDto } from './booking.mapper';

describe('toBookingDto', () => {
  it('answers every booking field in camelCase with ISO date-times', () => {
    const entity: BookingEntity = Object.assign(new BookingEntity(), {
      id: '0b9f4a1e-6a55-4a57-9a43-0f6f5a1c2d3e',
      roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
      title: 'Weekly sync',
      organizerEmail: 'ada@example.com',
      startsAt: new Date('2030-01-07T09:00:00.000Z'),
      endsAt: new Date('2030-01-07T10:00:00.000Z'),
      confirmationStatus: ConfirmationStatusEnum.PENDING,
      confirmationAttempts: 0,
      createdAt: new Date('2029-12-01T08:00:00.000Z'),
      updatedAt: new Date('2029-12-02T08:30:00.000Z'),
    });

    expect(toBookingDto(entity)).toEqual({
      id: '0b9f4a1e-6a55-4a57-9a43-0f6f5a1c2d3e',
      roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
      title: 'Weekly sync',
      organizerEmail: 'ada@example.com',
      startsAt: '2030-01-07T09:00:00.000Z',
      endsAt: '2030-01-07T10:00:00.000Z',
      confirmationStatus: 'PENDING',
      confirmationAttempts: 0,
      createdAt: '2029-12-01T08:00:00.000Z',
      updatedAt: '2029-12-02T08:30:00.000Z',
    });
  });
});

import { isEndAfterStart, parseBookingInstant } from './booking-time-range.util';

describe('parseBookingInstant', () => {
  it('returns the instant of an ISO date-time', () => {
    expect(parseBookingInstant('2030-01-07T09:00:00.000Z')).toEqual(new Date('2030-01-07T09:00:00.000Z'));
  });

  it('returns null for a value that does not parse to an instant', () => {
    expect(parseBookingInstant('2030-W02-1')).toBeNull();
  });
});

describe('isEndAfterStart', () => {
  const start = new Date('2030-01-07T09:00:00.000Z');

  it('is true when the end is strictly later', () => {
    expect(isEndAfterStart(start, new Date('2030-01-07T09:00:00.001Z'))).toBe(true);
  });

  it('is false when the end equals the start', () => {
    expect(isEndAfterStart(start, new Date('2030-01-07T09:00:00.000Z'))).toBe(false);
  });

  it('is false when the end is earlier', () => {
    expect(isEndAfterStart(start, new Date('2030-01-07T08:59:59.999Z'))).toBe(false);
  });
});

import { BOOKING_TITLE_MAX_LENGTH } from '@roombook/contract';
import type { ObjectSchema, ValidationError } from 'yup';
import { createBookingFormSchema, editBookingFormSchema } from './booking-form.schema';
import type { CreateBookingFormValues, EditBookingFormValues } from './booking-form.schema';

const validEdit: EditBookingFormValues = {
  title: 'Planning',
  startsAt: '2030-01-07T09:00',
  endsAt: '2030-01-07T10:00',
};

const validCreate: CreateBookingFormValues = {
  ...validEdit,
  roomId: 'a1b2c3d4-0000-4000-8000-000000000001',
  organizerEmail: 'ann@example.com',
};

const invalidPaths = <T extends EditBookingFormValues>(schema: ObjectSchema<T>, values: T): Promise<string[]> =>
  schema.validate(values, { abortEarly: false }).then(
    () => [],
    (error: ValidationError) => error.inner.map((inner) => inner.path ?? ''),
  );

describe('createBookingFormSchema', () => {
  it('accepts a valid form', async () => {
    expect(await invalidPaths(createBookingFormSchema, validCreate)).toEqual([]);
  });

  it('accepts a title of exactly the maximum length', async () => {
    const title = 'a'.repeat(BOOKING_TITLE_MAX_LENGTH);

    expect(await invalidPaths(createBookingFormSchema, { ...validCreate, title })).toEqual([]);
  });

  it.each<[string, Partial<CreateBookingFormValues>, string]>([
    ['a missing room', { roomId: '' }, 'roomId'],
    ['an empty title', { title: '' }, 'title'],
    ['a title longer than the maximum', { title: 'a'.repeat(BOOKING_TITLE_MAX_LENGTH + 1) }, 'title'],
    ['an invalid email', { organizerEmail: 'not-an-email' }, 'organizerEmail'],
    ['a missing email', { organizerEmail: '' }, 'organizerEmail'],
    ['a missing start', { startsAt: '' }, 'startsAt'],
    ['a missing end', { endsAt: '' }, 'endsAt'],
    ['an end equal to the start', { endsAt: validCreate.startsAt }, 'endsAt'],
    ['an end earlier than the start', { endsAt: '2030-01-07T08:59' }, 'endsAt'],
  ])('rejects %s', async (_, override, path) => {
    expect(await invalidPaths(createBookingFormSchema, { ...validCreate, ...override })).toEqual([path]);
  });
});

describe('editBookingFormSchema', () => {
  it('accepts a valid form of title, start and end only', async () => {
    expect(await invalidPaths(editBookingFormSchema, validEdit)).toEqual([]);
  });

  it.each<[string, Partial<EditBookingFormValues>, string]>([
    ['an empty title', { title: '' }, 'title'],
    ['a title longer than the maximum', { title: 'a'.repeat(BOOKING_TITLE_MAX_LENGTH + 1) }, 'title'],
    ['a missing start', { startsAt: '' }, 'startsAt'],
    ['a missing end', { endsAt: '' }, 'endsAt'],
    ['an end equal to the start', { endsAt: validEdit.startsAt }, 'endsAt'],
    ['an end earlier than the start', { endsAt: '2030-01-06T10:00' }, 'endsAt'],
  ])('rejects %s', async (_, override, path) => {
    expect(await invalidPaths(editBookingFormSchema, { ...validEdit, ...override })).toEqual([path]);
  });
});

import { renderHook } from '@testing-library/react';
import { validate, version } from 'uuid';
import { useIdempotencyKey } from './use-idempotency-key';

describe('useIdempotencyKey', () => {
  it('returns a UUID v4 and the same value on every call until release', () => {
    const { result, rerender } = renderHook(() => useIdempotencyKey());

    const first = result.current.getKey();
    rerender();

    expect(validate(first)).toBe(true);
    expect(version(first)).toBe(4);
    expect(result.current.getKey()).toBe(first);
    expect(result.current.getKey()).toBe(first);
  });

  it('returns a different UUID after release', () => {
    const { result } = renderHook(() => useIdempotencyKey());
    const first = result.current.getKey();

    result.current.release();
    const second = result.current.getKey();

    expect(validate(second)).toBe(true);
    expect(version(second)).toBe(4);
    expect(second).not.toBe(first);
    expect(result.current.getKey()).toBe(second);
  });
});

