import { BookingEntity } from '@roombook/backend-common';
import { BookingDto } from '@roombook/contract';

export const toBookingDto = (entity: BookingEntity): BookingDto => ({
  id: entity.id,
  roomId: entity.roomId,
  title: entity.title,
  organizerEmail: entity.organizerEmail,
  startsAt: entity.startsAt.toISOString(),
  endsAt: entity.endsAt.toISOString(),
  confirmationStatus: entity.confirmationStatus,
  confirmationAttempts: entity.confirmationAttempts,
  createdAt: entity.createdAt.toISOString(),
  updatedAt: entity.updatedAt.toISOString(),
});

export const parseBookingInstant = (value: string): Date | null => {
  const instant = new Date(value);
  return Number.isNaN(instant.getTime()) ? null : instant;
};

export const isEndAfterStart = (startsAt: Date, endsAt: Date): boolean => endsAt.getTime() > startsAt.getTime();

import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { UserEvent } from '@testing-library/user-event';
import { ConfirmationStatusEnum, ErrorCodeEnum } from '@roombook/contract';
import type { BookingDto, RoomDto } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { createBooking } from '../../services/booking.service';
import { BookingCreateForm } from './booking-create-form';

jest.mock('../../services/booking.service', () => ({ createBooking: jest.fn() }));

const mockedCreateBooking = createBooking as jest.MockedFunction<typeof createBooking>;

const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const rooms: RoomDto[] = [{ id: 'a1b2c3d4-0000-4000-8000-000000000001', name: 'Room 01', capacity: 2 }];
const START = '2030-01-07T09:00';
const END = '2030-01-07T10:00';

const created: BookingDto = {
  id: 'b1b2c3d4-0000-4000-8000-000000000001',
  roomId: rooms[0].id,
  title: 'Planning',
  organizerEmail: 'ann@example.com',
  startsAt: new Date(START).toISOString(),
  endsAt: new Date(END).toISOString(),
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

const form = () => screen.getByRole('form', { name: 'New booking' });
const field = (label: string) => within(form()).getByLabelText(label);
const setTime = (label: string, value: string) => fireEvent.change(field(label), { target: { value } });
const submit = (user: UserEvent) => user.click(within(form()).getByRole('button', { name: 'Create booking' }));
const keyOfCall = (index: number) => mockedCreateBooking.mock.calls[index][1];

const fillForm = async (user: UserEvent, end = END) => {
  await user.selectOptions(field('Room'), 'Room 01');
  await user.type(field('Title'), 'Planning');
  await user.type(field('Organizer email'), 'ann@example.com');
  setTime('Start', START);
  setTime('End', end);
};

const renderForm = () => {
  const onCreated = jest.fn();
  render(<BookingCreateForm rooms={rooms} onCreated={onCreated} />);
  return { user: userEvent.setup(), onCreated };
};

describe('BookingCreateForm', () => {
  beforeEach(() => {
    mockedCreateBooking.mockReset();
    mockedCreateBooking.mockResolvedValue(created);
  });

  it('renders a form named New booking with its five fields and the submit button', () => {
    renderForm();

    expect(within(form()).getByRole('combobox', { name: 'Room' })).toBeInTheDocument();
    expect(within(form()).getByRole('textbox', { name: 'Title' })).toBeInTheDocument();
    expect(within(form()).getByRole('textbox', { name: 'Organizer email' })).toBeInTheDocument();
    expect(field('Start')).toHaveAttribute('type', 'datetime-local');
    expect(field('End')).toHaveAttribute('type', 'datetime-local');
    expect(within(form()).getByRole('button', { name: 'Create booking' })).toBeInTheDocument();
  });

  it('shows a field error and sends no request when the end is before the start', async () => {
    const { user, onCreated } = renderForm();
    await fillForm(user, '2030-01-07T08:00');

    await submit(user);

    expect(await within(form()).findByText('End must be later than start')).toBeInTheDocument();
    expect(field('End')).toBeInvalid();
    expect(mockedCreateBooking).not.toHaveBeenCalled();
    expect(onCreated).not.toHaveBeenCalled();
  });

  it('creates the booking with UTC ISO times and a UUID key, then clears the form and calls onCreated', async () => {
    const { user, onCreated } = renderForm();
    await fillForm(user);

    await submit(user);

    await waitFor(() => expect(onCreated).toHaveBeenCalledTimes(1));
    expect(mockedCreateBooking).toHaveBeenCalledTimes(1);
    expect(mockedCreateBooking).toHaveBeenCalledWith(
      {
        roomId: rooms[0].id,
        title: 'Planning',
        organizerEmail: 'ann@example.com',
        startsAt: new Date(START).toISOString(),
        endsAt: new Date(END).toISOString(),
      },
      expect.stringMatching(UUID_V4),
    );
    expect(field('Room')).toHaveValue('');
    expect(field('Title')).toHaveValue('');
    expect(field('Organizer email')).toHaveValue('');
    expect(field('Start')).toHaveValue('');
    expect(field('End')).toHaveValue('');
  });

  it('uses the same key for an unchanged resubmit after a rejection that is not an ApiError', async () => {
    const { user, onCreated } = renderForm();
    mockedCreateBooking.mockRejectedValueOnce(new Error('Network Error'));
    await fillForm(user);

    await submit(user);
    expect(await within(form()).findByRole('alert')).toHaveTextContent('Network Error');
    expect(field('Title')).toHaveValue('Planning');
    await submit(user);

    await waitFor(() => expect(onCreated).toHaveBeenCalledTimes(1));
    expect(mockedCreateBooking).toHaveBeenCalledTimes(2);
    expect(keyOfCall(1)).toBe(keyOfCall(0));
    expect(within(form()).queryByRole('alert')).not.toBeInTheDocument();
  });

  it('shows the message of an ApiError and uses a new key for the next submit', async () => {
    const { user, onCreated } = renderForm();
    mockedCreateBooking.mockRejectedValueOnce(
      new ApiError({ statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'Room not found' }),
    );
    await fillForm(user);

    await submit(user);
    expect(await within(form()).findByRole('alert')).toHaveTextContent('Room not found');
    expect(onCreated).not.toHaveBeenCalled();
    await submit(user);

    await waitFor(() => expect(mockedCreateBooking).toHaveBeenCalledTimes(2));
    expect(keyOfCall(1)).toMatch(UUID_V4);
    expect(keyOfCall(1)).not.toBe(keyOfCall(0));
  });

  it('uses a new key for the submit after a success', async () => {
    const { user, onCreated } = renderForm();
    await fillForm(user);
    await submit(user);
    await waitFor(() => expect(onCreated).toHaveBeenCalledTimes(1));

    await fillForm(user);
    await submit(user);

    await waitFor(() => expect(onCreated).toHaveBeenCalledTimes(2));
    expect(keyOfCall(1)).toMatch(UUID_V4);
    expect(keyOfCall(1)).not.toBe(keyOfCall(0));
  });

  it.each(['Room', 'Title', 'Organizer email', 'Start', 'End'])(
    'uses a new key when %s changes after a network error',
    async (label) => {
      const { user } = renderForm();
      mockedCreateBooking.mockRejectedValueOnce(new Error('Network Error'));
      await fillForm(user);
      await submit(user);
      await within(form()).findByRole('alert');

      const control = field(label);
      if (label === 'Room') {
        await user.selectOptions(control, '');
        await user.selectOptions(control, 'Room 01');
      } else if (label === 'Start') {
        setTime(label, '2030-01-07T08:30');
      } else if (label === 'End') {
        setTime(label, '2030-01-07T11:00');
      } else {
        await user.type(control, 'x');
        await user.keyboard('{Backspace}');
      }
      await submit(user);

      await waitFor(() => expect(mockedCreateBooking).toHaveBeenCalledTimes(2));
      expect(keyOfCall(1)).not.toBe(keyOfCall(0));
    },
  );
});

import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ConfirmationStatusEnum, ErrorCodeEnum } from '@roombook/contract';
import type { BookingDto } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { updateBooking } from '../../services/booking.service';
import { BookingEditDialog } from './booking-edit-dialog';

jest.mock('../../services/booking.service', () => ({ updateBooking: jest.fn() }));

const mockedUpdateBooking = updateBooking as jest.MockedFunction<typeof updateBooking>;

const START = '2030-01-07T09:00';
const END = '2030-01-07T10:00';
const NEW_END = '2030-01-07T11:30';

const booking: BookingDto = {
  id: 'b1b2c3d4-0000-4000-8000-000000000001',
  roomId: 'a1b2c3d4-0000-4000-8000-000000000001',
  title: 'Planning',
  organizerEmail: 'ann@example.com',
  startsAt: new Date(START).toISOString(),
  endsAt: new Date(END).toISOString(),
  confirmationStatus: ConfirmationStatusEnum.SENT,
  confirmationAttempts: 1,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

const dialog = () => screen.getByRole('dialog', { name: 'Edit booking' });
const field = (label: string) => within(dialog()).getByLabelText(label);
const button = (name: string) => within(dialog()).getByRole('button', { name });

const renderDialog = () => {
  const handlers = { onClose: jest.fn(), onSaved: jest.fn() };
  render(<BookingEditDialog booking={booking} {...handlers} />);
  return { user: userEvent.setup(), ...handlers };
};

describe('BookingEditDialog', () => {
  beforeEach(() => {
    mockedUpdateBooking.mockReset();
    mockedUpdateBooking.mockResolvedValue(booking);
  });

  it('renders a dialog named Edit booking prefilled with title, start and end in local time', () => {
    renderDialog();

    expect(field('Title')).toHaveValue('Planning');
    expect(field('Start')).toHaveValue(START);
    expect(field('End')).toHaveValue(END);
  });

  it('saves title, start and end as UTC ISO and then calls onSaved', async () => {
    const { user, onSaved, onClose } = renderDialog();
    await user.clear(field('Title'));
    await user.type(field('Title'), 'Retro');
    fireEvent.change(field('End'), { target: { value: NEW_END } });

    await user.click(button('Save'));

    await waitFor(() => expect(onSaved).toHaveBeenCalledTimes(1));
    expect(mockedUpdateBooking).toHaveBeenCalledTimes(1);
    expect(mockedUpdateBooking).toHaveBeenCalledWith(booking.id, {
      title: 'Retro',
      startsAt: new Date(START).toISOString(),
      endsAt: new Date(NEW_END).toISOString(),
    });
    expect(onClose).not.toHaveBeenCalled();
  });

  it('shows a field error and sends no request when the end is not later than the start', async () => {
    const { user, onSaved } = renderDialog();
    fireEvent.change(field('End'), { target: { value: START } });

    await user.click(button('Save'));

    expect(await within(dialog()).findByText('End must be later than start')).toBeInTheDocument();
    expect(mockedUpdateBooking).not.toHaveBeenCalled();
    expect(onSaved).not.toHaveBeenCalled();
  });

  it('shows the message of an ApiError and stays open', async () => {
    mockedUpdateBooking.mockRejectedValue(
      new ApiError({ statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND, message: 'Booking not found' }),
    );
    const { user, onSaved, onClose } = renderDialog();

    await user.click(button('Save'));

    expect(await within(dialog()).findByRole('alert')).toHaveTextContent('Booking not found');
    expect(onSaved).not.toHaveBeenCalled();
    expect(onClose).not.toHaveBeenCalled();
  });

  it('calls onClose without a request when Cancel is chosen', async () => {
    const { user, onClose, onSaved } = renderDialog();

    await user.click(button('Cancel'));

    expect(onClose).toHaveBeenCalledTimes(1);
    expect(mockedUpdateBooking).not.toHaveBeenCalled();
    expect(onSaved).not.toHaveBeenCalled();
  });
});

import { CreateBookingDto } from '@roombook/contract';
import { bookingFingerprint } from './booking-fingerprint.util';

describe('bookingFingerprint', () => {
  const booking: CreateBookingDto = {
    roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
    title: 'Weekly sync',
    organizerEmail: 'ada@example.com',
    startsAt: '2030-01-01T10:00:00.000Z',
    endsAt: '2030-01-01T11:00:00.000Z',
  };

  it('returns 64 lower-case hex characters', () => {
    expect(bookingFingerprint(booking)).toMatch(/^[0-9a-f]{64}$/);
  });

  it('returns the same value whatever the property order', () => {
    const reordered: CreateBookingDto = {
      endsAt: booking.endsAt,
      startsAt: booking.startsAt,
      organizerEmail: booking.organizerEmail,
      title: booking.title,
      roomId: booking.roomId,
    };

    expect(bookingFingerprint(reordered)).toBe(bookingFingerprint(booking));
  });

  it.each([
    ['roomId', '7c1d2e3f-4a5b-4c6d-8e7f-9a0b1c2d3e4f'],
    ['title', 'Weekly sync!'],
    ['organizerEmail', 'grace@example.com'],
    ['startsAt', '2030-01-01T10:00:00Z'],
    ['endsAt', '2030-01-01T11:00:00Z'],
  ] as const)('returns a different value when %s differs', (field, value) => {
    expect(bookingFingerprint({ ...booking, [field]: value })).not.toBe(bookingFingerprint(booking));
  });
});

import { render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ConfirmationStatusEnum, ErrorCodeEnum } from '@roombook/contract';
import type { BookingDto } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { deleteBooking } from '../../services/booking.service';
import { BookingDeleteDialog } from './booking-delete-dialog';

jest.mock('../../services/booking.service', () => ({ deleteBooking: jest.fn() }));

const mockedDeleteBooking = deleteBooking as jest.MockedFunction<typeof deleteBooking>;

const booking: BookingDto = {
