import { Test } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { BookingEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum } from '@roombook/contract';
import { BookingRepository } from './booking.repository';

const BOOKING_ID = '0b9f4a1e-6a55-4a57-9a43-0f6f5a1c2d3e';
const ROOM_ID = '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10';

const bookingEntity = (): BookingEntity =>
  Object.assign(new BookingEntity(), {
    id: BOOKING_ID,
    roomId: ROOM_ID,
    title: 'Weekly sync',
    organizerEmail: 'ada@example.com',
    startsAt: new Date('2030-01-07T09:00:00.000Z'),
    endsAt: new Date('2030-01-07T10:00:00.000Z'),
    confirmationStatus: ConfirmationStatusEnum.PENDING,
    confirmationAttempts: 0,
    createdAt: new Date('2029-12-01T08:00:00.000Z'),
    updatedAt: new Date('2029-12-01T08:00:00.000Z'),
  });

describe('BookingRepository', () => {
  let repository: BookingRepository;
  let findAndCount: jest.Mock;
  let findOneBy: jest.Mock;
  let query: jest.Mock;

  beforeEach(async () => {
    findAndCount = jest.fn().mockResolvedValue([[bookingEntity()], 1]);
    findOneBy = jest.fn();
    query = jest.fn();
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingRepository,
        { provide: getRepositoryToken(BookingEntity), useValue: { findAndCount, findOneBy, query } },
      ],
    }).compile();
    repository = moduleRef.get(BookingRepository);
  });

  describe('findPage', () => {
    it('orders by start then id and pages with the requested limit', async () => {
      await expect(repository.findPage({ page: 3, limit: 5 })).resolves.toEqual([[bookingEntity()], 1]);

      expect(findAndCount).toHaveBeenCalledWith({
        where: {},
        order: { startsAt: 'ASC', id: 'ASC' },
        skip: 10,
        take: 5,
      });
    });

    it('restricts rows and total to the room when a roomId is given', async () => {
      await repository.findPage({ page: 1, limit: 10, roomId: ROOM_ID });

      expect(findAndCount).toHaveBeenCalledWith({
        where: { roomId: ROOM_ID },
        order: { startsAt: 'ASC', id: 'ASC' },
        skip: 0,
        take: 10,
      });
    });
  });

  describe('findById', () => {
    it('returns the booking', async () => {
      const entity = bookingEntity();
      findOneBy.mockResolvedValue(entity);

      await expect(repository.findById(BOOKING_ID)).resolves.toBe(entity);
      expect(findOneBy).toHaveBeenCalledWith({ id: BOOKING_ID });
    });

    it('returns null for an unknown booking', async () => {
      findOneBy.mockResolvedValue(null);

      await expect(repository.findById(BOOKING_ID)).resolves.toBeNull();
    });
  });

  describe('updateIfTimeRangeValid', () => {
    it('applies only the sent fields in one conditional update that sets updated_at', async () => {
      const entity = bookingEntity();
      query.mockResolvedValue([[entity], 1]);

      await expect(
        repository.updateIfTimeRangeValid(BOOKING_ID, { endsAt: '2030-01-07T11:00:00.000Z' }),
      ).resolves.toBe(entity);

      expect(query).toHaveBeenCalledTimes(1);
      const [sql, parameters] = query.mock.calls[0];
      expect(sql).toMatch(/^UPDATE "bookings"/);
      expect(sql).toContain('"title" = COALESCE($2::varchar, "title")');
      expect(sql).toContain('"starts_at" = COALESCE($3::timestamptz, "starts_at")');
      expect(sql).toContain('"ends_at" = COALESCE($4::timestamptz, "ends_at")');
      expect(sql).toContain('"updated_at" = now()');
      expect(sql).toContain('COALESCE($4::timestamptz, "ends_at") > COALESCE($3::timestamptz, "starts_at")');
      expect(sql).toContain('RETURNING');
      expect(parameters).toEqual([BOOKING_ID, null, null, new Date('2030-01-07T11:00:00.000Z')]);
    });

    it('passes every sent field', async () => {
      query.mockResolvedValue([[bookingEntity()], 1]);

      await repository.updateIfTimeRangeValid(BOOKING_ID, {
        title: 'Planning',
        startsAt: '2030-01-07T08:00:00.000Z',
        endsAt: '2030-01-07T08:30:00.000Z',
      });

      expect(query.mock.calls[0][1]).toEqual([
        BOOKING_ID,
        'Planning',
        new Date('2030-01-07T08:00:00.000Z'),
        new Date('2030-01-07T08:30:00.000Z'),
      ]);
    });

    it('returns null when no row matched', async () => {
      query.mockResolvedValue([[], 0]);

      await expect(repository.updateIfTimeRangeValid(BOOKING_ID, { title: 'Planning' })).resolves.toBeNull();
    });
  });

  describe('deleteById', () => {
    it('deletes in one statement and returns the deleted booking', async () => {
      const entity = bookingEntity();
      query.mockResolvedValue([[entity], 1]);

      await expect(repository.deleteById(BOOKING_ID)).resolves.toBe(entity);

      expect(query).toHaveBeenCalledTimes(1);
      const [sql, parameters] = query.mock.calls[0];
      expect(sql).toMatch(/^DELETE FROM "bookings" WHERE "id" = \$1 RETURNING/);
      expect(parameters).toEqual([BOOKING_ID]);
    });

    it('returns null when the booking does not exist', async () => {
      query.mockResolvedValue([[], 0]);

      await expect(repository.deleteById(BOOKING_ID)).resolves.toBeNull();
    });
  });
});

import { Test } from '@nestjs/testing';
import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum, CreateBookingDto } from '@roombook/contract';
import { DataSource } from 'typeorm';
import { toBookingDto } from './booking.mapper';
import { ClaimBookingOutcomeEnum } from './claim-booking-result.dto';
import { IdempotentBookingRepository } from './idempotent-booking.repository';

const KEY = '5d3c8a44-2f0e-4b7a-9c1d-6e8f0a1b2c3d';
const FINGERPRINT = 'a'.repeat(64);

const booking: CreateBookingDto = {
  roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
  title: 'Weekly sync',
  organizerEmail: 'ada@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
};

const savedBooking = (): BookingEntity =>
  Object.assign(new BookingEntity(), {
    id: '0b9f4a1e-6a55-4a57-9a43-0f6f5a1c2d3e',
    roomId: booking.roomId,
    title: booking.title,
    organizerEmail: booking.organizerEmail,
    startsAt: new Date(booking.startsAt),
    endsAt: new Date(booking.endsAt),
    confirmationStatus: ConfirmationStatusEnum.PENDING,
    confirmationAttempts: 0,
    createdAt: new Date('2029-12-01T08:00:00.000Z'),
    updatedAt: new Date('2029-12-01T08:00:00.000Z'),
  });

describe('IdempotentBookingRepository', () => {
  let repository: IdempotentBookingRepository;
  let manager: { save: jest.Mock; insert: jest.Mock };
  let queryRunner: Record<
    'connect' | 'startTransaction' | 'commitTransaction' | 'rollbackTransaction' | 'release',
    jest.Mock
  >;
  let createQueryRunner: jest.Mock;

  beforeEach(async () => {
    manager = { save: jest.fn().mockResolvedValue(savedBooking()), insert: jest.fn().mockResolvedValue(undefined) };
    queryRunner = {
      connect: jest.fn(),
      startTransaction: jest.fn(),
      commitTransaction: jest.fn(),
      rollbackTransaction: jest.fn(),
      release: jest.fn(),
    };
    createQueryRunner = jest.fn().mockReturnValue({ ...queryRunner, manager });
    const moduleRef = await Test.createTestingModule({
      providers: [IdempotentBookingRepository, { provide: DataSource, useValue: { createQueryRunner } }],
    }).compile();
    repository = moduleRef.get(IdempotentBookingRepository);
  });

  describe('claim', () => {
    it('inserts the booking and the idempotency row in one transaction and answers CREATED', async () => {
      const result = await repository.claim(KEY, FINGERPRINT, booking);

      expect(result).toEqual({ outcome: ClaimBookingOutcomeEnum.CREATED, booking: toBookingDto(savedBooking()) });
      expect(createQueryRunner).toHaveBeenCalledTimes(1);
      expect(queryRunner.startTransaction).toHaveBeenCalledTimes(1);
      expect(manager.save).toHaveBeenCalledWith(BookingEntity, {
        roomId: booking.roomId,
        title: booking.title,
        organizerEmail: booking.organizerEmail,
        startsAt: new Date(booking.startsAt),
        endsAt: new Date(booking.endsAt),
      });
      expect(manager.insert).toHaveBeenCalledWith(IdempotencyKeyEntity, {
        key: KEY,
        requestFingerprint: FINGERPRINT,
        responseStatus: 201,
        responseBody: toBookingDto(savedBooking()),
      });
      expect(queryRunner.commitTransaction).toHaveBeenCalledTimes(1);
      expect(queryRunner.rollbackTransaction).not.toHaveBeenCalled();
      expect(queryRunner.release).toHaveBeenCalledTimes(1);
    });

    it('rolls back and rejects when the idempotency row cannot be inserted', async () => {
      const failure = new Error('duplicate key value violates unique constraint');
      manager.insert.mockRejectedValue(failure);

      await expect(repository.claim(KEY, FINGERPRINT, booking)).rejects.toBe(failure);

      expect(queryRunner.commitTransaction).not.toHaveBeenCalled();
      expect(queryRunner.rollbackTransaction).toHaveBeenCalledTimes(1);
      expect(queryRunner.release).toHaveBeenCalledTimes(1);
    });
  });
});

import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
