    (error: unknown) => (error instanceof RpcException ? error.getError() : error),
  );

describe('BookingService', () => {
  let service: BookingService;
  let repository: Record<'findPage' | 'findById' | 'updateIfTimeRangeValid' | 'deleteById', jest.Mock>;

  beforeEach(async () => {
    repository = { findPage: jest.fn(), findById: jest.fn(), updateIfTimeRangeValid: jest.fn(), deleteById: jest.fn() };
    const moduleRef = await Test.createTestingModule({
      providers: [BookingService, { provide: BookingRepository, useValue: repository }],
    }).compile();
    service = moduleRef.get(BookingService);
  });

  it('lists a page of mapped bookings', async () => {
    repository.findPage.mockResolvedValue([[bookingEntity()], 7]);

    await expect(service.listBookings({ page: 2, limit: 5 })).resolves.toEqual({
      items: [toBookingDto(bookingEntity())],
      total: 7,
      page: 2,
      limit: 5,
    });
    expect(repository.findPage).toHaveBeenCalledWith({ page: 2, limit: 5 });
  });

  it('finds a booking by id', async () => {
    repository.findById.mockResolvedValue(bookingEntity());

    await expect(service.findBookingById(BOOKING_ID)).resolves.toEqual(toBookingDto(bookingEntity()));
    expect(repository.findById).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('raises 404 for an unknown booking', async () => {
    repository.findById.mockResolvedValue(null);

    await expect(errorOf(service.findBookingById(BOOKING_ID))).resolves.toEqual({
      statusCode: 404,
      errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND,
      message: 'Booking not found',
    });
  });

  describe('updateBooking', () => {
    it('returns the stored booking unchanged when no field is sent', async () => {
      repository.findById.mockResolvedValue(bookingEntity());

      await expect(service.updateBooking({ id: BOOKING_ID, changes: {} })).resolves.toEqual(
        toBookingDto(bookingEntity()),
      );
      expect(repository.updateIfTimeRangeValid).not.toHaveBeenCalled();
    });

    it('raises 404 when no field is sent and the booking is missing', async () => {
      repository.findById.mockResolvedValue(null);

      await expect(errorOf(service.updateBooking({ id: BOOKING_ID, changes: {} }))).resolves.toEqual(
        expect.objectContaining({ statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND }),
      );
    });

    it.each(['startsAt', 'endsAt'] as const)('raises 400 when %s does not parse to an instant', async (field) => {
      await expect(
        errorOf(service.updateBooking({ id: BOOKING_ID, changes: { [field]: '2030-W02-1' } })),
      ).resolves.toEqual({
        statusCode: 400,
        errorCode: ErrorCodeEnum.VALIDATION,
        message: 'startsAt and endsAt must be valid date-times',
      });
      expect(repository.updateIfTimeRangeValid).not.toHaveBeenCalled();
    });

    it('returns the updated booking', async () => {
      const updated = Object.assign(bookingEntity(), { title: 'Planning' });
      repository.updateIfTimeRangeValid.mockResolvedValue(updated);

      await expect(service.updateBooking({ id: BOOKING_ID, changes: { title: 'Planning' } })).resolves.toEqual(
        toBookingDto(updated),
      );
      expect(repository.updateIfTimeRangeValid).toHaveBeenCalledWith(BOOKING_ID, { title: 'Planning' });
    });

    it('raises 404 when the update matched no row and the booking is missing', async () => {
      repository.updateIfTimeRangeValid.mockResolvedValue(null);
      repository.findById.mockResolvedValue(null);

      await expect(
        errorOf(service.updateBooking({ id: BOOKING_ID, changes: { title: 'Planning' } })),
      ).resolves.toEqual(expect.objectContaining({ statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND }));
    });

    it('raises 400 when the update matched no row and the booking exists', async () => {
      repository.updateIfTimeRangeValid.mockResolvedValue(null);
      repository.findById.mockResolvedValue(bookingEntity());

      await expect(
        errorOf(service.updateBooking({ id: BOOKING_ID, changes: { endsAt: '2030-01-07T08:00:00.000Z' } })),
      ).resolves.toEqual({
        statusCode: 400,
        errorCode: ErrorCodeEnum.VALIDATION,
        message: 'endsAt must be later than startsAt',
      });
    });
  });

  it('returns the deleted booking', async () => {
    repository.deleteById.mockResolvedValue(bookingEntity());

    await expect(service.deleteBooking(BOOKING_ID)).resolves.toEqual(toBookingDto(bookingEntity()));
    expect(repository.deleteById).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('raises 404 when the booking to delete does not exist', async () => {
    repository.deleteById.mockResolvedValue(null);

    await expect(errorOf(service.deleteBooking(BOOKING_ID))).resolves.toEqual(
      expect.objectContaining({ statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND }),
    );
  });
});

import { ApiRouteEnum, IDEMPOTENCY_KEY_HEADER } from '@roombook/contract';
import type {
  BookingDto,
  CreateBookingDto,
  ListBookingsQueryDto,
  PagedBookingsDto,
  UpdateBookingDto,
} from '@roombook/contract';
import { apiClient } from './api-client';

const BOOKINGS_PATH = `/${ApiRouteEnum.BOOKINGS}`;

export const listBookings = async ({ page, limit, roomId }: ListBookingsQueryDto): Promise<PagedBookingsDto> => {
  const params = roomId ? { page, limit, roomId } : { page, limit };
  const { data } = await apiClient.get<PagedBookingsDto>(BOOKINGS_PATH, { params });
  return data;
};

export const createBooking = async (booking: CreateBookingDto, idempotencyKey: string): Promise<BookingDto> => {
  const { data } = await apiClient.post<BookingDto>(BOOKINGS_PATH, booking, {
    headers: { [IDEMPOTENCY_KEY_HEADER]: idempotencyKey },
  });
  return data;
};

export const updateBooking = async (id: string, changes: UpdateBookingDto): Promise<BookingDto> => {
  const { data } = await apiClient.patch<BookingDto>(`${BOOKINGS_PATH}/${id}`, changes);
  return data;
};

export const deleteBooking = async (id: string): Promise<void> => {
  await apiClient.delete(`${BOOKINGS_PATH}/${id}`);
};

const pad = (value: number): string => String(value).padStart(2, '0');

export const toUtcIso = (localInputValue: string): string => new Date(localInputValue).toISOString();

export const toLocalInputValue = (iso: string): string => {
  const date = new Date(iso);
  const day = `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
  return `${day}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
};

export const formatDateTime = (iso: string): string => new Date(iso).toLocaleString();

