import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { BookingEntity } from '@roombook/backend-common';
import { ListBookingsQueryDto, UpdateBookingDto } from '@roombook/contract';
import { Repository } from 'typeorm';

type ReturnedBookingRows = [BookingEntity[], number];

const RETURNING_BOOKING = `RETURNING
  "id",
  "room_id" AS "roomId",
  "title",
  "organizer_email" AS "organizerEmail",
  "starts_at" AS "startsAt",
  "ends_at" AS "endsAt",
  "confirmation_status" AS "confirmationStatus",
  "confirmation_attempts" AS "confirmationAttempts",
  "created_at" AS "createdAt",
  "updated_at" AS "updatedAt"`;

const toInstantOrNull = (value: string | undefined): Date | null => (value === undefined ? null : new Date(value));

@Injectable()
export class BookingRepository {
  constructor(@InjectRepository(BookingEntity) private readonly bookings: Repository<BookingEntity>) {}

  findPage(query: ListBookingsQueryDto): Promise<[BookingEntity[], number]> {
    return this.bookings.findAndCount({
      where: query.roomId ? { roomId: query.roomId } : {},
      order: { startsAt: 'ASC', id: 'ASC' },
      skip: (query.page - 1) * query.limit,
      take: query.limit,
    });
  }

  findById(id: string): Promise<BookingEntity | null> {
    return this.bookings.findOneBy({ id });
  }

  async updateIfTimeRangeValid(id: string, changes: UpdateBookingDto): Promise<BookingEntity | null> {
    const [rows]: ReturnedBookingRows = await this.bookings.query(
      `UPDATE "bookings"
      SET
        "title" = COALESCE($2::varchar, "title"),
        "starts_at" = COALESCE($3::timestamptz, "starts_at"),
        "ends_at" = COALESCE($4::timestamptz, "ends_at"),
        "updated_at" = now()
      WHERE "id" = $1
        AND COALESCE($4::timestamptz, "ends_at") > COALESCE($3::timestamptz, "starts_at")
      ${RETURNING_BOOKING}`,
      [id, changes.title ?? null, toInstantOrNull(changes.startsAt), toInstantOrNull(changes.endsAt)],
    );
    return rows[0] ?? null;
  }

  async deleteById(id: string): Promise<BookingEntity | null> {
    const [rows]: ReturnedBookingRows = await this.bookings.query(
      `DELETE FROM "bookings" WHERE "id" = $1 ${RETURNING_BOOKING}`,
      [id],
    );
    return rows[0] ?? null;
  }
}

import { useEffect, useState } from 'react';
import Alert from '@mui/material/Alert';
import Box from '@mui/material/Box';
import LinearProgress from '@mui/material/LinearProgress';
import Paper from '@mui/material/Paper';
import Typography from '@mui/material/Typography';
import { MAX_PAGE_SIZE } from '@roombook/contract';
import type { BookingDto, RoomDto } from '@roombook/contract';
import { listRooms } from '../../services/room.service';
import { BookingCreateForm } from './booking-create-form';
import { BookingDeleteDialog } from './booking-delete-dialog';
import { BookingEditDialog } from './booking-edit-dialog';
import { BookingRoomFilter } from './booking-room-filter';
import { BookingsTable } from './bookings-table';
import { useBookings } from './use-bookings';

export function BookingsPage() {
  const { bookings, total, loading, errorMessage, page, roomId, setPage, setRoomId, reload } = useBookings();
  const [rooms, setRooms] = useState<RoomDto[]>([]);
  const [roomsErrorMessage, setRoomsErrorMessage] = useState<string | null>(null);
  const [editedBooking, setEditedBooking] = useState<BookingDto | null>(null);
  const [deletedBooking, setDeletedBooking] = useState<BookingDto | null>(null);

  useEffect(() => {
    let active = true;
    listRooms(1, MAX_PAGE_SIZE)
      .then((data) => active && setRooms(data.items))
      .catch((e: unknown) => active && setRoomsErrorMessage(e instanceof Error ? e.message : String(e)));
    return () => {
      active = false;
    };
  }, []);

  const handleSaved = (): void => {
    setEditedBooking(null);
    reload();
  };

  const handleDeleted = (): void => {
    setDeletedBooking(null);
    reload();
  };

  return (
    <>
      <Typography variant="h4" component="h1" gutterBottom>
        Bookings
      </Typography>
      {roomsErrorMessage && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {roomsErrorMessage}
        </Alert>
      )}
      <BookingCreateForm rooms={rooms} onCreated={reload} />
      <Box sx={{ mb: 2 }}>
        <BookingRoomFilter rooms={rooms} roomId={roomId} onChange={setRoomId} />
      </Box>
      {loading && <LinearProgress aria-label="Loading bookings" />}
      {errorMessage && <Alert severity="error">{errorMessage}</Alert>}
      {!loading && !errorMessage && bookings.length === 0 && <Typography>No bookings found.</Typography>}
      {bookings.length > 0 && (
        <Paper>
          <BookingsTable
            bookings={bookings}
            rooms={rooms}
            total={total}
            page={page}
            onPageChange={setPage}
            onEdit={setEditedBooking}
            onDelete={setDeletedBooking}
          />
        </Paper>
      )}
      {editedBooking && (
        <BookingEditDialog booking={editedBooking} onClose={() => setEditedBooking(null)} onSaved={handleSaved} />
      )}
      {deletedBooking && (
        <BookingDeleteDialog
          booking={deletedBooking}
          onClose={() => setDeletedBooking(null)}
          onDeleted={handleDeleted}
        />
      )}
    </>
  );
}

import { HttpStatus, Injectable } from '@nestjs/common';
import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
import { CreateBookingDto } from '@roombook/contract';
import { DataSource, EntityManager } from 'typeorm';
import { toBookingDto } from './booking.mapper';
import { ClaimBookingOutcomeEnum, ClaimBookingResultDto } from './claim-booking-result.dto';

@Injectable()
export class IdempotentBookingRepository {
  constructor(private readonly dataSource: DataSource) {}

  async claim(key: string, fingerprint: string, booking: CreateBookingDto): Promise<ClaimBookingResultDto> {
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();
    try {
      const result = await this.insertBookingWithKey(queryRunner.manager, key, fingerprint, booking);
      await queryRunner.commitTransaction();
      return result;
    } catch (error) {
      await queryRunner.rollbackTransaction();
      throw error;
    } finally {
      await queryRunner.release();
    }
  }

  private async insertBookingWithKey(
    manager: EntityManager,
    key: string,
    fingerprint: string,
    booking: CreateBookingDto,
  ): Promise<ClaimBookingResultDto> {
    const saved = await manager.save(BookingEntity, {
      roomId: booking.roomId,
      title: booking.title,
      organizerEmail: booking.organizerEmail,
      startsAt: new Date(booking.startsAt),
      endsAt: new Date(booking.endsAt),
    });
    const responseBody = toBookingDto(saved);
    await manager.insert(IdempotencyKeyEntity, {
      key,
      requestFingerprint: fingerprint,
      responseStatus: HttpStatus.CREATED,
      responseBody,
    });
    return { outcome: ClaimBookingOutcomeEnum.CREATED, booking: responseBody };
  }
}

