import { Injectable } from '@nestjs/common';
import { BOUNCE_EMAIL_DOMAIN, CONFIRMATION_JOB_ATTEMPTS, RETRY_EMAIL_DOMAIN } from '@roombook/contract';

@Injectable()
export class SimulatedConfirmationSender {
  send(organizerEmail: string, attempt: number): boolean {
    const address = organizerEmail.toLowerCase();
    if (address.endsWith(`@${BOUNCE_EMAIL_DOMAIN}`)) {
      return false;
    }
    return !address.endsWith(`@${RETRY_EMAIL_DOMAIN}`) || attempt >= CONFIRMATION_JOB_ATTEMPTS;
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { isErrorResponse, NATS_CLIENT, NatsRequestUtil } from '@roombook/backend-common';
import {
  BookingDto,
  BookingIdMessageDto,
  BookingPatternEnum,
  ErrorCodeEnum,
  RecordConfirmationResultDto,
} from '@roombook/contract';

@Injectable()
export class BookingClient {
  constructor(@Inject(NATS_CLIENT) private readonly client: ClientProxy) {}

  async findBooking(id: string): Promise<BookingDto | null> {
    try {
      return await NatsRequestUtil.send<BookingDto, BookingIdMessageDto>(
        this.client,
        BookingPatternEnum.FIND_BY_ID,
        { id },
      );
    } catch (error) {
      if (isErrorResponse(error) && error.errorCode === ErrorCodeEnum.BOOKING_NOT_FOUND) {
        return null;
      }
      throw error;
    }
  }

  recordResult(report: RecordConfirmationResultDto): Promise<BookingDto | null> {
    return NatsRequestUtil.send<BookingDto | null, RecordConfirmationResultDto>(
      this.client,
      BookingPatternEnum.RECORD_CONFIRMATION,
      report,
    );
  }
}

import { Injectable } from '@nestjs/common';
import { CONFIRMATION_JOB_ATTEMPTS, ConfirmationStatusEnum } from '@roombook/contract';
import { BookingClient } from './booking.client';
import { SimulatedConfirmationSender } from './simulated-confirmation-sender';

const statusAfterFailure = (attempt: number): ConfirmationStatusEnum =>
  attempt >= CONFIRMATION_JOB_ATTEMPTS ? ConfirmationStatusEnum.FAILED : ConfirmationStatusEnum.PENDING;

@Injectable()
export class ConfirmationService {
  constructor(
    private readonly bookingClient: BookingClient,
    private readonly sender: SimulatedConfirmationSender,
  ) {}

  async processAttempt(bookingId: string, attempt: number): Promise<void> {
    const booking = await this.bookingClient.findBooking(bookingId);
    if (!booking || booking.confirmationStatus !== ConfirmationStatusEnum.PENDING) {
      return;
    }
    const sent = this.sender.send(booking.organizerEmail, attempt);
    const status = sent ? ConfirmationStatusEnum.SENT : statusAfterFailure(attempt);
    await this.bookingClient.recordResult({ bookingId, status, attempts: attempt });
    if (!sent) {
      throw new Error(`Confirmation attempt ${attempt} for booking ${bookingId} failed`);
    }
  }
}

